# @heaven3d-part branding/branding.py  -- a slice of Heaven3D.py: edit it here, then run `python build.py` (see src/README.md)
# #############################################################################
# SECTION 17 —  BRANDING  (embedded logo, welcome banner, Unreal boot splash)
# #############################################################################
#
#  Everything the engine needs to brand itself lives in this one section and
#  travels inside Heaven3D.py — there are no image files to ship alongside it,
#  so `pyinstaller --onefile Heaven3D.py` still produces a single artefact.
#
#  NO NEW DEPENDENCIES.  The two modules imported below (base64, io) are part
#  of the Python standard library — nothing extra to `pip install`.  Decoding
#  is done with pygame.image, which the engine already requires, and the
#  pixels are uploaded through moderngl, which it also already requires.
#
#  WHAT YOU GET
#    * heavenLOGO.png  → the window/taskbar icon and the mark at the head of
#                        the editor toolbar (drawn by _build_ui).
#    * Heaven3D.png    → the full-bleed welcome banner on the boot splash.
#
#  WHEN THE SPLASH RUNS
#    First launch on a machine shows the full WELCOME presentation.  Every
#    launch after that shows the short loading version.  Controlled by:
#        python Heaven3D.py --no-splash        skip it
#        python Heaven3D.py --splash           force the welcome version
#        python Heaven3D.py --reset-welcome    treat the next boot as the first
#
# #############################################################################

import base64 as _h3d_base64      # stdlib — not a new dependency
import io as _h3d_io              # stdlib — not a new dependency


